    steps = {
      {
        order = 1,
        marker = "*",
        depth = 1,
        instruction = "Zone into present-day Xarcabard on Scholar level 66 or higher for a cutscene. You need to have all Scholar Artifact quests completed to receive the cutscene and begin this quest.",
        action = "travel",
        entities = { "Xarcabard", "Scholar", "Artifact" },
        zones = {  },
