      {
        order = 2,
        marker = "**",
        depth = 2,
        instruction = "You have to until game day change after completing the previous quest in order to get this cutscene in Xarcabard.",
        action = "note",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 3,
        marker = "*",
        depth = 1,
        instruction = "Obtain a Scholar's Testimony from Orcs in East Ronfaure (S) or the The Eldieme Necropolis (S). The Orcs in East Ronfaure (S) are weaker and respawn in only 5 minutes (as opposed to 15 minutes in Eldieme), and they are easier to reach.",
