        instruction = "Trade the Scholar's Testimony to the Indescript Markings at (G-8)/(H-8) in present-day Xarcabard and you will be transported to the Throne Room.",
        action = "trade",
        entities = { "Scholar's Testimony", "Xarcabard", "Throne Room" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = { "G-8", "H-8" },
